def calculate_sequence(N):
    a = [0] * (N + 1)
    if N >= 1:
        a[1] = 1
    if N >= 2:
        a[2] = 1

    for n in range(3, N + 1):
        # a_n = a_{a_{n-1}} + a_{n - a_{n-1}}
        k = a[n-1]
        # Safety check: k must be <= N
        if k > N:
            # This should not happen if the sequence remains slow growing
            # but it's good practice if we were worried about bounds
            return None
        a[n] = a[k] + a[n - k]
    return a[1:]

